270	func TestConfirm(t *testing.T) {
271		s, _ := open(t)
272		mustPoint(t, s, "P1", "取水口")
273		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
274		mustLimit(t, s, "P1", "pH", 7.0, at(10, 0))
275		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
276	
277		// 缺一个项目的适用上限：拒绝，保持待判定，不留部分结论
278		mustSample(t, s, "S1", "P1", at(12, 0),
279			Measurement{Item: "pH", Value: 7.5}, Measurement{Item: "SS", Value: 10})
280		if _, err := s.Confirm("S1"); !errors.Is(err, ErrMissingLimit) {
281			t.Fatalf("missing limit should reject, got %v", err)
282		}
283		_, ok, err := s.LatestResult("P1")
284		if err != nil || ok {
285			t.Fatalf("no confirmed sample expected")
286		}
287		list, _ := s.ListByPoint("P1")
288		if len(list) != 1 || list[0].Status != StatusPending || list[0].Results != nil {
289			t.Fatalf("rejected confirm must leave sample pending without partial results: %+v", list)
290		}
291	
292		// 补齐限值后可再次确认
293		mustLimit(t, s, "P1", "SS", 15.0, at(1, 0))
294		smp1, err := s.Confirm("S1")
295		if err != nil {
296			t.Fatalf("Confirm after backfill: %v", err)
297		}
298		if smp1.Status != StatusConfirmed || !smp1.Exceeded {
299			t.Fatalf("expected confirmed & exceeded, got %+v", smp1)
300		}
301		// pH 取不晚于采样时间的最近一版（7.0@09-10），7.5 超标；SS 10 ≤ 15 达标
302		if smp1.Results[0].Limit != 7.0 || !smp1.Results[0].Exceeded {
303			t.Fatalf("pH result wrong: %+v", smp1.Results[0])
304		}
305		if smp1.Results[1].Limit != 15.0 || smp1.Results[1].Exceeded {
306			t.Fatalf("SS result wrong: %+v", smp1.Results[1])
307		}
308	
309		// 采样时间恰好等于生效时间时使用新值
310		mustSample(t, s, "S2", "P1", at(10, 0), Measurement{Item: "pH", Value: 7.5})
311		smp2, err := s.Confirm("S2")
312		if err != nil {
313			t.Fatalf("Confirm S2: %v", err)
314		}
315		if smp2.Results[0].Limit != 7.0 || !smp2.Results[0].LimitEffective.Equal(at(10, 0)) {
316			t.Fatalf("boundary effective time should use new value, got %+v", smp2.Results[0])
317		}
318		if !smp2.Exceeded {
319			t.Fatalf("7.5 > 7.0 should exceed")
320		}
321	
322		// 等于上限算达标
323		mustSample(t, s, "S3", "P1", at(11, 0), Measurement{Item: "pH", Value: 7.0})
324		smp3, _ := s.Confirm("S3")
325		if smp3.Exceeded || smp3.Results[0].Exceeded {
326			t.Fatalf("equal to limit should pass, got %+v", smp3.Results[0])
327		}
328	
329		// 重复确认直接返回已保存结果；之后补录限值不改变已确认结果
330		mustLimit(t, s, "P1", "pH", 100.0, at(10, 12))
331		again, err := s.Confirm("S2")
332		if err != nil {
333			t.Fatalf("re-confirm: %v", err)
334		}
335		if again.Results[0].Limit != 7.0 || !again.Exceeded {
336			t.Fatalf("confirmed result must not change, got %+v", again.Results[0])
337		}
338	
339		if _, err := s.Confirm("nope"); !errors.Is(err, ErrUnknownSample) {
340			t.Fatalf("unknown sample, got %v", err)
341		}
342	}
343	
344	// 所有项目都能完成判定、但本地保存结果失败时，本次确认必须整体失败：
345	// 已算出的逐项结果与整份样品的超标标记都不能生效，样品保持待判定，
346	// 采样点上一份已确认样品仍是最近有效结果；保存条件恢复后可重新确认，
347	// 按采样当时适用的限值完整保存逐项判定（一项超标、一项等于上限）。
348	func TestConfirmPersistFailure(t *testing.T) {
349		s, dir := open(t)
350		mustPoint(t, s, "P1", "取水口")
351		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
352		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
353	
354		resultByItem := func(rs []ItemResult) map[string]ItemResult {
355			m := make(map[string]ItemResult, len(rs))
356			for _, r := range rs {
357				m[r.Item] = r
358			}
359			return m
360		}
361		find := func(list []Sample, id string) Sample {
362			t.Helper()
363			for _, smp := range list {
364				if smp.ID == id {
365					return smp
366				}
367			}
368			t.Fatalf("sample %q missing from list %+v", id, list)
369			return Sample{}
370		}
371	
372		// 采样时间较早、正常保存的已确认样品：pH 7 ≤ 8，达标
373		mustSample(t, s, "S1", "P1", at(5, 0), Measurement{Item: "pH", Value: 7})
374		conf1, err := s.Confirm("S1")
375		if err != nil || conf1.Status != StatusConfirmed || conf1.Exceeded {
376			t.Fatalf("Confirm S1 setup: %+v err=%v", conf1, err)
377		}
378	
379		// 更晚的待判定样品：两个项目采样时均有适用上限，pH 超上限，COD 恰好等于上限
380		mustSample(t, s, "S2", "P1", at(10, 0),
381			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
382		// 对照样品：缺少适用上限，用来证明本检查区分判定错误与保存错误
383		mustSample(t, s, "S3", "P1", at(2, 0), Measurement{Item: "SS", Value: 1})
384	
385		// 只让确认结果的保存失败：采样点、限值和样品准备此前均已成功落盘。
386		// 占用临时文件路径为目录后，原子写的 WriteFile 必然失败，不依赖目录权限。
387		tmp := filepath.Join(dir, "water-data.json.tmp")
388		if err := os.Mkdir(tmp, 0o755); err != nil {
389			t.Fatalf("block persist: %v", err)
390		}
391	
392		// 同样无法保存的条件下，缺上限在判定阶段即以 ErrMissingLimit 拒绝，
393		// 根本走不到保存；S2 的失败必须是与之不同的保存错误。
394		if _, err := s.Confirm("S3"); !errors.Is(err, ErrMissingLimit) {
395			t.Fatalf("missing limit should be a judgment error, got %v", err)
396		}
397		got, err := s.Confirm("S2")
398		if err == nil {
399			t.Fatal("Confirm should fail when results cannot be saved")
400		}
401		if errors.Is(err, ErrMissingLimit) {
402			t.Fatalf("save failure must not be reported as missing limit: %v", err)
403		}
404		if got.ID != "" || got.Status == StatusConfirmed {
405			t.Fatalf("failed save must not return a confirmed sample: %+v", got)
406		}
407	
408		// 按采样点查看：原采样时间、项目和测量值保持，状态待判定，
409		// 没有逐项判定结果，整份样品也不能带上失败尝试算出的超标标记。
410		list, err := s.ListByPoint("P1")
411		if err != nil {
412			t.Fatalf("ListByPoint after failed save: %v", err)
413		}
414		if len(list) != 3 {
415			t.Fatalf("list should keep all three samples, got %+v", list)
416		}
417		failed := find(list, "S2")
418		if failed.Status != StatusPending || failed.Exceeded || failed.Results != nil {
419			t.Fatalf("failed confirm must leave pending sample without results: %+v", failed)
420		}
421		if !failed.SampledAt.Equal(at(10, 0)) || len(failed.Measurements) != 2 {
422			t.Fatalf("sampled time and measurements changed: %+v", failed)
423		}
424		values := map[string]float64{}
425		for _, m := range failed.Measurements {
426			values[m.Item] = m.Value
427		}
428		if values["pH"] != 9 || values["COD"] != 30 {
429			t.Fatalf("measurements changed: %+v", failed.Measurements)
430		}
431		if s3 := find(list, "S3"); s3.Status != StatusPending || s3.Results != nil {
432			t.Fatalf("S3 should stay pending without results: %+v", s3)
433		}
434	
435		// 同一份已打开的数据存放中，最近有效结果仍是较早的 S1，
436		// 结论与所用限值保持原样，不能被采样更晚的失败尝试顶替。
437		latest, ok, err := s.LatestResult("P1")
438		if err != nil || !ok || latest.ID != "S1" {
439			t.Fatalf("latest valid result should stay S1, got %+v ok=%v err=%v", latest, ok, err)
440		}
441		if latest.Exceeded || len(latest.Results) != 1 {
442			t.Fatalf("S1 conclusion changed: %+v", latest)
443		}
444		r1 := latest.Results[0]
445		if r1.Item != "pH" || r1.Value != 7 || r1.Limit != 8.0 || !r1.LimitEffective.Equal(at(1, 0)) || r1.Exceeded {
446			t.Fatalf("S1 result and limit must remain intact: %+v", r1)
447		}
448	
449		// 恢复正常保存条件
450		if err := os.Remove(tmp); err != nil {
451			t.Fatalf("restore persist: %v", err)
452		}
453		// 采样时间之后才生效的新版上限不能影响按采样当时适用限值的重新判定
454		mustLimit(t, s, "P1", "pH", 9.5, at(15, 0))
455	
456		// 重新确认：不能被当成已确认而直接返回失败尝试的状态，必须重新判定并成功保存
457		conf2, err := s.Confirm("S2")
458		if err != nil {
459			t.Fatalf("retry Confirm after save restored: %v", err)
460		}
461		checkSaved := func(smp Sample, label string) {
462			t.Helper()
463			if smp.Status != StatusConfirmed || !smp.SampledAt.Equal(at(10, 0)) || !smp.Exceeded || len(smp.Results) != 2 {
464				t.Fatalf("%s: confirmed sample wrong: %+v", label, smp)
465			}
466			rs := resultByItem(smp.Results)
467			ph, cod := rs["pH"], rs["COD"]
468			if ph.Value != 9 || ph.Limit != 8.0 || !ph.LimitEffective.Equal(at(1, 0)) || !ph.Exceeded {
469				t.Fatalf("%s: pH should be 9 > 8@09-01 exceeded, got %+v", label, ph)
470			}
471			if cod.Value != 30 || cod.Limit != 30.0 || !cod.LimitEffective.Equal(at(1, 0)) || cod.Exceeded {
472				t.Fatalf("%s: COD 30 == limit 30@09-01 should pass, got %+v", label, cod)
473			}
474		}
475		checkSaved(conf2, "retry result")
476	
477		// 重复确认返回已保存结果
478		again, err := s.Confirm("S2")
479		if err != nil {
480			t.Fatalf("re-confirm S2: %v", err)
481		}
482		checkSaved(again, "re-confirm")
483		// 原样品的结论与所用限值保持原样，不受新限值影响
484		keep1, err := s.Confirm("S1")
485		if err != nil || keep1.Exceeded || keep1.Results[0].Limit != 8.0 || !keep1.Results[0].LimitEffective.Equal(at(1, 0)) {
486			t.Fatalf("S1 must remain confirmed as saved, got %+v err=%v", keep1, err)
487		}
488	
489		// 按采样点查看的记录与最近有效结果一致
490		list2, err := s.ListByPoint("P1")
491		if err != nil {
492			t.Fatalf("ListByPoint after recovery: %v", err)
493		}
494		saved := find(list2, "S2")
495		latest2, ok, err := s.LatestResult("P1")
496		if err != nil || !ok || latest2.ID != "S2" {
497			t.Fatalf("later S2 should now be the latest valid result, got %+v ok=%v err=%v", latest2, ok, err)
498		}
499		checkSaved(saved, "list")
500		checkSaved(latest2, "latest")
501		if s3 := find(list2, "S3"); s3.Status != StatusPending || s3.Results != nil || s3.Exceeded {
502			t.Fatalf("S3 should still be pending with no failure marker: %+v", s3)
503		}
504	
505		// 重新打开同一数据存放：成功保存的结果落盘，失败尝试不留任何痕迹
506		if err := s.Close(); err != nil {
507			t.Fatalf("Close: %v", err)
508		}
509		s2, err := Open(dir)
510		if err != nil {
511			t.Fatalf("reopen: %v", err)
512		}
513		defer s2.Close()
514		list3, err := s2.ListByPoint("P1")
515		if err != nil {
516			t.Fatalf("reopened ListByPoint: %v", err)
517		}
518		latest3, ok, err := s2.LatestResult("P1")
519		if err != nil || !ok {
520			t.Fatalf("reopened latest result: %+v ok=%v err=%v", latest3, ok, err)
521		}
522		checkSaved(find(list3, "S2"), "reopened list")
523		checkSaved(latest3, "reopened latest")
524		if r := find(list3, "S1"); r.Status != StatusConfirmed || r.Exceeded || r.Results[0].Limit != 8.0 {
525			t.Fatalf("reopened S1 changed: %+v", r)
526		}
527		if r := find(list3, "S3"); r.Status != StatusPending || r.Results != nil {
528			t.Fatalf("reopened S3 should stay pending: %+v", r)
529		}
530	}
