1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9		"time"
10	)
11	
12	// 限值只能属于登记它的（采样点，项目）：两个字段各自相同才算同一组。
13	// 编号与项目名内部允许包含 U+0000，不能用单字符拼接键把不同组合撞成一组。
14	func TestLimitGroupOwnership(t *testing.T) {
15		s, _ := open(t)
16		zeroPoint := "P\x00A" // 〈零〉在编号中间
17		zeroItem := "A\x00B"  // 〈零〉在项目名中间
18		mustPoint(t, s, zeroPoint, "带零编号")
19		mustPoint(t, s, "P", "普通编号")
20	
21		eff := at(1, 0)
22		// 两组在同一时刻分别登记上限 10 和 5，互不报生效时间重复
23		mustLimit(t, s, zeroPoint, "B", 10, eff)
24		mustLimit(t, s, "P", zeroItem, 5, eff)
25	
26		sampled := at(2, 0)
27		mustSample(t, s, "SZ", zeroPoint, sampled, Measurement{Item: "B", Value: 7})
28		mustSample(t, s, "SN", "P", sampled, Measurement{Item: zeroItem, Value: 7})
29	
30		rz, err := s.Confirm("SZ")
31		if err != nil {
32			t.Fatalf("Confirm SZ: %v", err)
33		}
34		if rz.Exceeded || len(rz.Results) != 1 {
35			t.Fatalf("7 <= 10 应达标: %+v", rz)
36		}
37		if r := rz.Results[0]; r.Item != "B" || r.Value != 7 || r.Limit != 10 ||
38			!r.LimitEffective.Equal(eff) || r.Exceeded {
39			t.Fatalf("前者判定依据错误: %+v", r)
40		}
41	
42		rn, err := s.Confirm("SN")
43		if err != nil {
44			t.Fatalf("Confirm SN: %v", err)
45		}
46		if !rn.Exceeded || len(rn.Results) != 1 {
47			t.Fatalf("7 > 5 应超标: %+v", rn)
48		}
49		if r := rn.Results[0]; r.Item != zeroItem || r.Value != 7 || r.Limit != 5 ||
50			!r.LimitEffective.Equal(eff) || !r.Exceeded {
51			t.Fatalf("后者判定依据错误: %+v", r)
52		}
53	
54		// 按采样点查看：各自只看到本组样品与本组判定依据
55		for _, c := range []struct {
56			point string
57			id    string
58			lim   float64
59			item  string
60		}{
61			{zeroPoint, "SZ", 10, "B"},
62			{"P", "SN", 5, zeroItem},
63		} {
64			list, err := s.ListByPoint(c.point)
65			if err != nil || len(list) != 1 {
66				t.Fatalf("ListByPoint(%q): %+v err=%v", c.point, list, err)
67			}
68			got := list[0]
69			if got.ID != c.id || len(got.Results) != 1 {
70				t.Fatalf("按点查看串组: %+v", got)
71			}
72			if r := got.Results[0]; r.Item != c.item || r.Limit != c.lim ||
73				!r.LimitEffective.Equal(eff) {
74				t.Fatalf("按点查看的判定依据错误: %+v", r)
75			}
76		}
77	}
